select trim(product_id) product_id, nullif(trim(product_category_name),'') category_name, nullif(trim(product_name_lenght),'')::int name_length, nullif(trim(product_description_lenght),'')::int description_length, nullif(trim(product_photos_qty),'')::int photos_count, nullif(trim(product_weight_g),'')::numeric weight_g, nullif(trim(product_length_cm),'')::numeric length_cm, nullif(trim(product_height_cm),'')::numeric height_cm, nullif(trim(product_width_cm),'')::numeric width_cm, run_id source_run_id, source_row_number
from {{ source('bronze','products') }} where run_id='{{ var("source_run_id") }}'::uuid
